// PLACEHOLDER normalizer — see n8n/README.md 'Providers'. Every ESP's
// inbound webhook payload shape differs (SendGrid Inbound Parse, Postmark
// Inbound, Mailgun Routes, ...). Adjust the field paths below to match
// your provider; the output shape is the ONLY contract Workflow 07 needs.
const body = $input.first().json.body ?? {};

const fromAddress = body.from || body.sender || body.envelope?.from || '';
const providerMessageId = body.messageId || body['Message-ID'] || body.message_id || undefined;
const occurredAt = body.date ? new Date(body.date).toISOString() : new Date().toISOString();
const summary = body.text || body.TextBody || body['stripped-text'] || body.subject || '(no body)';

return [{
  json: {
    channel: 'email',
    fromAddress,
    providerMessageId,
    occurredAt,
    summary,
  },
}];
